DECLARE
V_COUNT INTEGER;
BEGIN
SELECT COUNT(TABLE_NAME) INTO V_COUNT from USER_TABLES where TABLE_NAME = '__EFMigrationsHistory';
IF V_COUNT = 0 THEN
Begin
BEGIN 
EXECUTE IMMEDIATE 'CREATE TABLE 
"__EFMigrationsHistory" (
    "MigrationId" NVARCHAR2(150) NOT NULL,
    "ProductVersion" NVARCHAR2(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
)';
END;

End;

END IF;
EXCEPTION
WHEN OTHERS THEN
    IF(SQLCODE != -942)THEN
        RAISE;
    END IF;
END;
/

BEGIN 
EXECUTE IMMEDIATE 'CREATE TABLE 
"TB_AUTOR" (
    "ID" NUMBER(10) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    "NOME" NVARCHAR2(100) NOT NULL,
    "NACIONALIDADE" NVARCHAR2(60),
    "DATA_NASCIMENTO" DATE,
    CONSTRAINT "PK_AUTOR" PRIMARY KEY ("ID")
)';
END;
/

BEGIN 
EXECUTE IMMEDIATE 'CREATE TABLE 
"TB_LIVRO" (
    "ID" NUMBER(10) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    "TITULO" NVARCHAR2(200) NOT NULL,
    "ISBN" NVARCHAR2(13) NOT NULL,
    "ANO_PUBLICACAO" NUMBER(10) NOT NULL,
    "DISPONIVEL" NUMBER(1) NOT NULL,
    "AUTOR_ID" NUMBER(10) NOT NULL,
    CONSTRAINT "PK_LIVRO" PRIMARY KEY ("ID"),
    CONSTRAINT "FK_LIVRO_AUTOR" FOREIGN KEY ("AUTOR_ID") REFERENCES "TB_AUTOR" ("ID")
)';
END;
/

BEGIN 
EXECUTE IMMEDIATE 'CREATE TABLE 
"TB_EMPRESTIMO" (
    "ID" NUMBER(10) GENERATED BY DEFAULT ON NULL AS IDENTITY NOT NULL,
    "NOME_LEITOR" NVARCHAR2(100) NOT NULL,
    "EMAIL_LEITOR" NVARCHAR2(150) NOT NULL,
    "DATA_EMPRESTIMO" TIMESTAMP(7) NOT NULL,
    "DATA_PREVISTA_DEVOLUCAO" TIMESTAMP(7) NOT NULL,
    "DATA_DEVOLUCAO" TIMESTAMP(7),
    "LIVRO_ID" NUMBER(10) NOT NULL,
    CONSTRAINT "PK_EMPRESTIMO" PRIMARY KEY ("ID"),
    CONSTRAINT "FK_EMPRESTIMO_LIVRO" FOREIGN KEY ("LIVRO_ID") REFERENCES "TB_LIVRO" ("ID")
)';
END;
/

CREATE INDEX "IX_EMPRESTIMO_LIVRO" ON "TB_EMPRESTIMO" ("LIVRO_ID")
/

CREATE INDEX "IX_LIVRO_AUTOR" ON "TB_LIVRO" ("AUTOR_ID")
/

CREATE UNIQUE INDEX "UX_LIVRO_ISBN" ON "TB_LIVRO" ("ISBN")
/

